using UnityEngine;

namespace ABCWonderworld.UI
{
    /// <summary>Shared UI sprites, font and palette. Generated by the setup pipeline at Resources/UiSkin.</summary>
    [CreateAssetMenu(menuName = "ABC Wonderworld/UI Skin", fileName = "UiSkin")]
    public sealed class UiSkin : ScriptableObject
    {
        public Font font;
        public Sprite rounded;     // 9-sliced rounded rectangle
        public Sprite circle;
        public Sprite ring;
        public Sprite star;
        public Sprite iconHome;
        public Sprite iconBack;
        public Sprite iconSpeaker;
        public Sprite iconPlay;
        public Sprite iconPause;
        public Sprite iconLock;
        public Sprite iconCheck;
        public Sprite iconArrow;
        public Sprite iconHand;
        public Sprite iconBook;
        public Sprite iconMusic;
        public Sprite iconPuzzle;
        public Sprite iconPencil;
        public Sprite iconSearch;
        public Sprite iconMatch;
        public Sprite iconStarOutline;
        public Sprite iconRefresh;

        public Color cream = new Color(1f, 0.96f, 0.88f);
        public Color ink = new Color(0.22f, 0.2f, 0.32f);
        public Color primary = new Color(1f, 0.55f, 0.25f);
        public Color secondary = new Color(0.3f, 0.7f, 0.95f);
        public Color success = new Color(0.35f, 0.8f, 0.4f);
        public Color gentle = new Color(1f, 0.8f, 0.35f);

        private static UiSkin _cached;
        public static UiSkin Load() => _cached != null ? _cached : (_cached = Resources.Load<UiSkin>("UiSkin"));

        /// <summary>Sprite for a vocabulary/prop key: an emoji code or a drawn item (draw:igloo).</summary>
        public static Sprite Picture(string key)
        {
            string name = Content.ArtKeys.ResourceName(key);
            return name == null ? null : Resources.Load<Sprite>("Pictures/" + name);
        }
    }
}
